package wordy

import (
	"strconv"
	"strings"
)

// Answer parses a math word problem and evaluates it left-to-right,
// ignoring the usual order of operations. It returns the answer and
// whether the question was a valid math problem.
func Answer(question string) (int, bool) {
	question = strings.TrimSuffix(question, "?")
	question = strings.TrimPrefix(question, "What is ")
	tokens := strings.Fields(question)
	if len(tokens) == 0 {
		return 0, false
	}

	n, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		var op string
		switch tokens[i] {
		case "plus", "minus":
			op = tokens[i]
		case "multiplied", "divided":
			if i+1 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			op = tokens[i]
			i++
		default:
			return 0, false
		}
		i++

		if i >= len(tokens) {
			return 0, false
		}
		m, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			n += m
		case "minus":
			n -= m
		case "multiplied":
			n *= m
		case "divided":
			n /= m
		}
	}

	return n, true
}
